import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  FiBookOpen,
  FiImage,
  FiMessageSquare,
  FiPlus,
  FiSettings,
  FiShield,
  FiArrowRight,
  FiMail,
  FiTrendingUp,
  FiRefreshCw,
  FiArrowUpRight,
} from 'react-icons/fi';
import { useNavigate } from 'react-router-dom';

import api from '../../services/api';
import { useLanguage } from '../../contexts/LanguageContext';
import AdminLoading from '../common/AdminLoading';

const AdminDashboard = () => {
  const navigate = useNavigate();
  const { language } = useLanguage();
  const isKhmer = language === 'km' || language === 'kh';

  const [dashboardData, setDashboardData] = useState({
    total_admin: 0,
    total_courses: 0,
    total_messages: 0,
    total_gallery: 0,
    total_videos: 0,
    total_schools: 0,
    recent_messages: [],
  });

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(new Date());
  const [showQuickMenu, setShowQuickMenu] = useState(false);

  const fetchStats = useCallback(async (isRefresh = false) => {
    isRefresh ? setRefreshing(true) : setLoading(true);
    const minDelay = new Promise((resolve) => setTimeout(resolve, 600));
    try {
      const [res] = await Promise.all([
        api.get('/api/admin/dashboard-stats'),
        minDelay,
      ]);
      if (res.data) {
        setDashboardData(res.data);
      }
    } catch (err) {
      console.warn('Dashboard stats fallback:', err);
      try {
        const [coursesRes, messagesRes, galleryRes, usersRes, videosRes] = await Promise.allSettled([
          api.get('/api/courses/'),
          api.get('/api/contact/'),
          api.get('/api/gallery/'),
          api.get('/api/admin/users'),
          api.get('/api/videos/'),
        ]);

        const getLen = (r) => (r.status === 'fulfilled' && Array.isArray(r.value.data) ? r.value.data.length : 0);

        setDashboardData({
          total_courses: getLen(coursesRes),
          total_messages: getLen(messagesRes),
          total_gallery: getLen(galleryRes),
          total_admin: getLen(usersRes),
          total_videos: getLen(videosRes),
          total_schools: 1,
          recent_messages: messagesRes.status === 'fulfilled' && Array.isArray(messagesRes.value.data) ? messagesRes.value.data.slice(0, 5) : [],
        });
      } catch (fallbackErr) {
        console.error('Fallback error:', fallbackErr);
      }
    } finally {
      setLastUpdated(new Date());
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    fetchStats();
  }, [fetchStats]);

  // Clean, Unified Top Stat Cards (No rainbow colors)
  const topStats = useMemo(() => [
    {
      id: 'courses',
      count: dashboardData.total_courses,
      label: isKhmer ? 'វគ្គសិក្សាទាំងអស់' : 'Total Courses',
      sublabel: isKhmer ? 'កម្មវិធីបណ្តុះបណ្តាល' : 'Training Programs',
      icon: FiBookOpen,
      path: '/courses',
    },
    {
      id: 'messages',
      count: dashboardData.total_messages,
      label: isKhmer ? 'សារទំនាក់ទំនង' : 'Contact Inquiries',
      sublabel: isKhmer ? 'សារពីភ្ញៀវចូលមើល' : 'Visitor Inquiries',
      icon: FiMessageSquare,
      path: '/messages',
    },
    {
      id: 'gallery',
      count: dashboardData.total_gallery,
      label: isKhmer ? 'រូបភាព Gallery' : 'Gallery Photos',
      sublabel: isKhmer ? 'រូបភាពសកម្មភាព' : 'Activity Photos',
      icon: FiImage,
      path: '/gallery',
    },
    {
      id: 'admin',
      count: dashboardData.total_admin,
      label: isKhmer ? 'អ្នកគ្រប់គ្រង' : 'Admin Accounts',
      sublabel: isKhmer ? 'គណនីគ្រប់គ្រងប្រព័ន្ធ' : 'Active Admins',
      icon: FiShield,
      path: '/settings',
    },
  ], [dashboardData, isKhmer]);

  // Unified Content breakdown metrics (Monochrome Navy / Blue)
  const contentMetrics = [
    { label: isKhmer ? 'វគ្គសិក្សា (Courses)' : 'Courses', value: dashboardData.total_courses },
    { label: isKhmer ? 'រូបភាព Gallery (Photos)' : 'Gallery Photos', value: dashboardData.total_gallery },
    { label: isKhmer ? 'វីដេអូបណ្តុះបណ្តាល (Videos)' : 'Videos', value: dashboardData.total_videos },
    { label: isKhmer ? 'សារទំនាក់ទំនង (Messages)' : 'Messages', value: dashboardData.total_messages },
    { label: isKhmer ? 'អ្នកគ្រប់គ្រង (Admin Users)' : 'Admin Users', value: dashboardData.total_admin },
  ];

  const totalContent = contentMetrics.reduce((sum, item) => sum + item.value, 0);
  const highestMetric = Math.max(...contentMetrics.map((item) => item.value), 1);

  // SVG Donut calculation
  const radius = 64;
  const circumference = 2 * Math.PI * radius;
  const primaryCount = dashboardData.total_courses;
  const otherCount = Math.max(totalContent - primaryCount, 0);
  const primaryStroke = totalContent > 0 ? (primaryCount / totalContent) * circumference : 0;

  if (loading) {
    return <AdminLoading label={isKhmer ? 'កំពុងផ្ទុកទិន្នន័យ...' : 'Loading statistics...'} />;
  }

  return (
    <main className={`min-h-screen bg-[#F8FAFC] p-4 md:p-6 lg:p-8 space-y-6 ${isKhmer ? 'font-khmer' : ''}`}>

      {/* =====================================================
          1. TOP WELCOME BANNER (CLEAN NAVY / SLATE)
      ===================================================== */}
      <section className="relative overflow-hidden rounded-2xl bg-slate-900 p-6 sm:p-8 text-white shadow-sm border border-slate-800">
        <div className="relative z-10 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-5">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-slate-800 text-slate-300 text-xs font-semibold mb-2.5">
              <span className="w-2 h-2 rounded-full bg-emerald-400" />
              SC Academy Control Center
            </div>
            <h1 className="text-2xl sm:text-3xl font-extrabold tracking-tight">
              {isKhmer ? 'សូមស្វាគមន៍មកកាន់ផ្ទាំងគ្រប់គ្រង Admin' : 'Welcome back, Admin'}
            </h1>
            <p className="mt-1 text-xs sm:text-sm text-slate-400 font-normal max-w-xl">
              {isKhmer
                ? 'តាមដាន និងគ្រប់គ្រងទិន្នន័យវគ្គសិក្សា រូបភាព និងសារទំនាក់ទំនងជាក់ស្តែង។'
                : 'Track and manage your real-time school programs, gallery, and contact inquiries.'}
            </p>
          </div>

          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={() => fetchStats(true)}
              disabled={refreshing}
              className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 font-semibold text-xs transition-colors"
            >
              <FiRefreshCw className={refreshing ? 'animate-spin' : ''} size={14} />
              <span>{isKhmer ? 'ផ្ទុកឡើងវិញ' : 'Refresh'}</span>
            </button>

            <div className="relative">
              <button
                type="button"
                onClick={() => setShowQuickMenu(!showQuickMenu)}
                className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-[#2563EB] hover:bg-[#1D4ED8] text-white font-bold text-xs shadow-sm transition-all active:scale-95"
              >
                <FiPlus size={15} />
                <span>Quick Action</span>
              </button>

              {/* Dropdown Menu */}
              {showQuickMenu && (
                <div className="absolute right-0 mt-2.5 w-52 rounded-xl bg-white p-1.5 shadow-xl border border-slate-200 z-50 animate-fade-in text-slate-800">
                  <button
                    type="button"
                    onClick={() => { setShowQuickMenu(false); navigate('/courses'); }}
                    className="w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-xs font-semibold hover:bg-slate-50 hover:text-[#2563EB] transition-colors text-left"
                  >
                    <FiBookOpen className="text-[#2563EB]" />
                    <span>{isKhmer ? 'គ្រប់គ្រងវគ្គសិក្សា' : 'Manage Courses'}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => { setShowQuickMenu(false); navigate('/gallery'); }}
                    className="w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-xs font-semibold hover:bg-slate-50 hover:text-[#2563EB] transition-colors text-left"
                  >
                    <FiImage className="text-[#2563EB]" />
                    <span>{isKhmer ? 'រូបភាព Gallery' : 'Upload Gallery'}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => { setShowQuickMenu(false); navigate('/messages'); }}
                    className="w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-xs font-semibold hover:bg-slate-50 hover:text-[#2563EB] transition-colors text-left"
                  >
                    <FiMessageSquare className="text-[#2563EB]" />
                    <span>{isKhmer ? 'សារទំនាក់ទំនង' : 'View Messages'}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => { setShowQuickMenu(false); navigate('/settings'); }}
                    className="w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-xs font-semibold hover:bg-slate-50 hover:text-[#2563EB] transition-colors text-left"
                  >
                    <FiSettings className="text-[#2563EB]" />
                    <span>{isKhmer ? 'ការកំណត់ប្រព័ន្ធ' : 'Admin Settings'}</span>
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* =====================================================
          2. TOP 4 STAT CARDS (CLEAN, MINIMALIST & PROFESSIONAL)
      ===================================================== */}
      <section className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-5">
        {topStats.map((stat) => {
          const Icon = stat.icon;
          return (
            <div
              key={stat.id}
              onClick={() => navigate(stat.path)}
              className="bg-white rounded-2xl p-5 sm:p-6 border border-slate-200 shadow-sm hover:border-slate-300 hover:shadow-md transition-all duration-200 cursor-pointer group flex flex-col justify-between"
            >
              <div className="flex items-start justify-between">
                <div className="w-11 h-11 rounded-xl bg-blue-50 border border-blue-100 flex items-center justify-center text-[#2563EB] group-hover:bg-[#2563EB] group-hover:text-white transition-colors duration-200">
                  <Icon size={20} />
                </div>
                <FiArrowUpRight className="text-slate-300 group-hover:text-[#2563EB] transition-colors" size={16} />
              </div>

              <div className="mt-5">
                <p className="text-3xl sm:text-4xl font-extrabold text-[#1E3A8A] tracking-tight tabular-nums">
                  {stat.count}
                </p>
                <h3 className="mt-1 text-sm font-bold text-slate-800">
                  {stat.label}
                </h3>
                <p className="text-xs text-slate-500 font-medium">
                  {stat.sublabel}
                </p>
              </div>
            </div>
          );
        })}
      </section>

      {/* =====================================================
          3. REAL CONTENT ANALYTICS & DISTRIBUTION
      ===================================================== */}
      <section className="grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* LEFT: CONTENT VOLUME & BREAKDOWN (8 cols) */}
        <div className="lg:col-span-8 bg-white rounded-2xl p-6 sm:p-7 border border-slate-200 shadow-sm flex flex-col justify-between">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-base font-bold text-slate-900">
                {isKhmer ? 'ការបែងចែកមាតិកាប្រព័ន្ធ' : 'Content & Records Analytics'}
              </h2>
              <p className="text-xs text-slate-500 font-normal mt-0.5">
                {isKhmer ? 'ទិន្នន័យជាក់ស្តែងនៃមាតិកាដែលកំពុងដំណើរការក្នុងប្រព័ន្ធ។' : 'Real-time volume of records currently active in the database.'}
              </p>
            </div>
            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-slate-100 text-slate-700 text-xs font-semibold">
              <FiTrendingUp size={13} className="text-[#2563EB]" /> Live Data
            </span>
          </div>

          {/* Progress Bars with Unified Clean Blue */}
          <div className="mt-6 space-y-4">
            {contentMetrics.map((metric) => (
              <div key={metric.label}>
                <div className="mb-1.5 flex items-center justify-between text-xs font-semibold">
                  <span className="text-slate-700">{metric.label}</span>
                  <span className="text-[#1E3A8A] font-extrabold tabular-nums">{metric.value}</span>
                </div>
                <div className="h-2 w-full rounded-full bg-slate-100 overflow-hidden">
                  <div
                    className="h-full rounded-full bg-[#2563EB] transition-all duration-700"
                    style={{ width: `${metric.value ? Math.max((metric.value / highestMetric) * 100, 6) : 0}%` }}
                  />
                </div>
              </div>
            ))}
          </div>

          <div className="mt-6 pt-4 border-t border-slate-100 flex items-center justify-between text-xs text-slate-400 font-medium">
            <span>{isKhmer ? 'ធ្វើបច្ចុប្បន្នភាពចុងក្រោយ' : 'Last refreshed'}: {lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            <span className="text-[#1E3A8A] font-bold">{isKhmer ? 'ទិន្នន័យសរុប' : 'Total Items'}: {totalContent}</span>
          </div>
        </div>

        {/* RIGHT: SYSTEM CONTENT PROPORTION (4 cols) */}
        <div className="lg:col-span-4 bg-white rounded-2xl p-6 sm:p-7 border border-slate-200 shadow-sm flex flex-col justify-between">
          <div>
            <h2 className="text-base font-bold text-slate-900">
              {isKhmer ? 'ផលធៀបមាតិកា' : 'Content Proportion'}
            </h2>
            <p className="text-xs text-slate-500 font-normal mt-0.5">
              {isKhmer ? 'ផលធៀបវគ្គសិក្សា និងមាតិកាផ្សេងៗ' : 'Courses vs Media Distribution'}
            </p>
          </div>

          {/* SVG Donut Chart (Clean Blue & Slate) */}
          <div className="my-5 flex flex-col items-center justify-center">
            <div className="relative w-40 h-40 flex items-center justify-center">
              <svg className="w-full h-full -rotate-90" viewBox="0 0 160 160">
                {/* Background Ring */}
                <circle
                  cx="80"
                  cy="80"
                  r={radius}
                  fill="transparent"
                  stroke="#E2E8F0"
                  strokeWidth="20"
                />
                {/* Primary Courses Arc (Clean Blue) */}
                {totalContent > 0 && (
                  <circle
                    cx="80"
                    cy="80"
                    r={radius}
                    fill="transparent"
                    stroke="#2563EB"
                    strokeWidth="20"
                    strokeDasharray={`${primaryStroke} ${circumference}`}
                    strokeDashoffset="0"
                    className="transition-all duration-700"
                  />
                )}
              </svg>

              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-2xl font-extrabold text-[#1E3A8A]">{totalContent}</span>
                <span className="text-[10px] uppercase font-bold text-slate-400">Total</span>
              </div>
            </div>

            {/* Inline Legend */}
            <div className="flex items-center gap-6 mt-3">
              <div className="flex items-center gap-2">
                <span className="w-3 h-3 rounded-sm bg-[#2563EB]" />
                <span className="text-xs font-semibold text-slate-700">{isKhmer ? 'វគ្គសិក្សា' : 'Courses'}</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="w-3 h-3 rounded-sm bg-[#E2E8F0]" />
                <span className="text-xs font-semibold text-slate-700">{isKhmer ? 'មាតិកាផ្សេងៗ' : 'Other Media'}</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4 border-t border-slate-100 pt-3.5 text-center">
            <div>
              <p className="text-base font-extrabold text-[#1E3A8A]">{dashboardData.total_courses}</p>
              <p className="text-xs text-slate-400 font-medium">{isKhmer ? 'វគ្គសិក្សា' : 'Courses'}</p>
            </div>
            <div>
              <p className="text-base font-extrabold text-[#1E3A8A]">{otherCount}</p>
              <p className="text-xs text-slate-400 font-medium">{isKhmer ? 'មាតិកាផ្សេងៗ' : 'Other'}</p>
            </div>
          </div>
        </div>
      </section>

      {/* =====================================================
          4. RECENT INQUIRIES & MESSAGES (CLEAN WHITE CARD)
      ===================================================== */}
      <section className="bg-white rounded-2xl p-6 sm:p-7 border border-slate-200 shadow-sm">
        <div className="flex items-center justify-between mb-5">
          <div>
            <h2 className="text-base font-bold text-slate-900">
              {isKhmer ? 'សារទំនាក់ទំនងថ្មីៗ' : 'Recent Inquiries & Messages'}
            </h2>
            <p className="text-xs text-slate-500 font-normal mt-0.5">
              {isKhmer ? 'សារ និងសំណួរដែលបានផ្ញើចេញពីទំព័រ Contact' : 'Direct messages submitted by website visitors.'}
            </p>
          </div>

          <button
            type="button"
            onClick={() => navigate('/messages')}
            className="inline-flex items-center gap-1.5 text-xs font-bold text-[#2563EB] hover:text-[#1D4ED8] transition-colors"
          >
            <span>{isKhmer ? 'មើលសារទាំងអស់' : 'View All Messages'}</span>
            <FiArrowRight size={14} />
          </button>
        </div>

        {dashboardData.recent_messages && dashboardData.recent_messages.length > 0 ? (
          <div className="divide-y divide-slate-100">
            {dashboardData.recent_messages.map((msg, index) => (
              <div key={msg.id || index} className="py-3 flex flex-col sm:flex-row sm:items-center justify-between gap-3 hover:bg-slate-50/70 px-2 rounded-xl transition-colors">
                <div className="flex items-start gap-3 min-w-0">
                  <div className="w-8 h-8 rounded-lg bg-blue-50 text-[#2563EB] flex items-center justify-center flex-shrink-0 mt-0.5">
                    <FiMail size={15} />
                  </div>
                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <p className="text-xs sm:text-sm font-bold text-slate-900 truncate">{msg.name || 'Anonymous'}</p>
                      {msg.email && <span className="text-xs text-slate-400 truncate">({msg.email})</span>}
                    </div>
                    <p className="text-xs text-slate-600 line-clamp-1 mt-0.5">{msg.subject || msg.message || 'No subject'}</p>
                  </div>
                </div>

                {msg.created_at && (
                  <span className="text-[11px] font-medium text-slate-400 flex-shrink-0">
                    {msg.created_at}
                  </span>
                )}
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-8 border border-dashed border-slate-200 rounded-xl">
            <FiMessageSquare size={24} className="mx-auto text-slate-300 mb-1.5" />
            <p className="text-xs font-bold text-slate-600">{isKhmer ? 'មិនទាន់មានសារទំនាក់ទំនងថ្មីទេ' : 'No contact messages yet'}</p>
            <p className="text-[11px] text-slate-400 mt-0.5">{isKhmer ? 'សារដែលភ្ញៀវផ្ញើមកនឹងបង្ហាញនៅទីនេះ' : 'Messages submitted on the contact page will appear here.'}</p>
          </div>
        )}
      </section>

    </main>
  );
};

export default AdminDashboard;
